    public function show(string $section, ?string $view = null): View
    {
        abort_unless(auth()->user()?->hasRole('super-admin'), 403);

        $sections = $this->sections();
        abort_unless(isset($sections[$section]), 404);

        $activeView = $view ?? str($sections[$section]['items'][0])->slug();
        abort_unless(collect($sections[$section]['items'])->map(fn (string $item) => str($item)->slug())->contains($activeView), 404);

        return view('admin.command.show', [
            'section' => $section,
            'activeView' => $activeView,
            'definition' => $sections[$section],
            'metrics' => $this->metrics($section),
            'managementLink' => $this->managementLink($section, $activeView),
            'moduleSummary' => $this->moduleSummary($section, $activeView, $sections[$section]),
        ]);
    }

