            'audit-logs/security-logs' => ['label' => 'View Security Logs', 'url' => route('admin.control-center.index', ['section' => 'audit-logs', 'view' => 'security-logs'])],
            default => null,
        };
    }

    private function metrics(string $section): array
    {
        return match ($section) {
            'employers' => ['All Companies' => Company::count(), 'Pending Approval' => Company::where('status', 'pending')->count(), 'Approved' => Company::where('status', 'verified')->count()],
            'job-seekers' => ['Candidates' => User::whereHas('roles', fn ($query) => $query->where('slug', 'job-seeker'))->count(), 'Incomplete Profiles' => User::whereHas('candidateProfile', fn ($query) => $query->where('profile_completion', '<', 100))->count(), 'Applications' => JobApplication::count()],
            'jobs' => ['All Jobs' => Job::count(), 'Active Jobs' => Job::where('status', 'published')->count(), 'Pending Jobs' => Job::where('status', 'draft')->count()],
            'recruitment' => ['Applications' => JobApplication::count(), 'Interview Scheduled' => JobApplication::where('status', 'Interview Scheduled')->count(), 'Offers Sent' => Offer::where('status', 'sent')->count()],
            'subscriptions' => ['Packages' => \App\Models\Package::count(), 'Active Subscriptions' => Subscription::where('status', 'active')->count(), 'Expiring Soon' => Subscription::whereBetween('expires_at', [today(), today()->addDays(30)])->count()],
            'payments' => ['Transactions' => Payment::count(), 'Paid' => Payment::where('status', 'paid')->count(), 'Revenue' => Payment::where('status', 'paid')->sum('amount')],
            'notifications' => ['Notification History' => PlatformNotification::count(), 'Unread' => PlatformNotification::whereNull('read_at')->count(), 'Enabled Channels' => 1],
            'interviews' => ['Today' => \App\Models\Interview::whereDate('scheduled_at', today())->count(), 'Upcoming' => \App\Models\Interview::where('scheduled_at', '>', now())->count(), 'Completed' => \App\Models\Interview::where('status', 'completed')->count()],
            'offers' => ['All Offers' => Offer::count(), 'Sent' => Offer::where('status', 'sent')->count(), 'Accepted' => Offer::where('status', 'accepted')->count()],
            'ai-api' => ['Configured APIs' => \App\Models\ApiIntegration::count(), 'Enabled APIs' => \App\Models\ApiIntegration::where('is_enabled', true)->count(), 'API Errors' => \App\Models\ApiIntegration::whereNotNull('last_error')->count()],
            default => ['Configured' => count($this->sections()[$section]['items']), 'Active Users' => User::where('is_active', true)->count(), 'System Status' => 'Ready'],
        };
    }

